CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gaming_stations (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, type TEXT NOT NULL, hourly_rate_paisa INTEGER NOT NULL, status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reservations (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, station_id INTEGER NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(station_id) REFERENCES gaming_stations(id));
CREATE TABLE IF NOT EXISTS memberships (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,plan TEXT NOT NULL,starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,status TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS teams (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,captain_id INTEGER NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(captain_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS team_members (team_id INTEGER NOT NULL,user_id INTEGER NOT NULL,status TEXT NOT NULL,PRIMARY KEY(team_id,user_id),FOREIGN KEY(team_id) REFERENCES teams(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS tournaments (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,format TEXT NOT NULL,fee_paisa INTEGER NOT NULL,status TEXT NOT NULL,created_by INTEGER NOT NULL,FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS registrations (id INTEGER PRIMARY KEY AUTOINCREMENT,tournament_id INTEGER NOT NULL,user_id INTEGER,team_id INTEGER,fee_paisa INTEGER NOT NULL,status TEXT NOT NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(team_id) REFERENCES teams(id));
CREATE TABLE IF NOT EXISTS sessions (id INTEGER PRIMARY KEY AUTOINCREMENT,reservation_id INTEGER NOT NULL,started_at TEXT NOT NULL,ended_at TEXT,status TEXT NOT NULL,charge_paisa INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(reservation_id) REFERENCES reservations(id));
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,amount_paisa INTEGER NOT NULL,method TEXT NOT NULL,reference TEXT,status TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS maintenance (id INTEGER PRIMARY KEY AUTOINCREMENT,station_id INTEGER NOT NULL,description TEXT NOT NULL,severity TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,resolved_at TEXT,FOREIGN KEY(station_id) REFERENCES gaming_stations(id));
